parameters.jsCode:
const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const data = JSON.parse(raw);
return [{ json: data }];

const products = $input.item.json.data;
const switches = products.filter(p => p.switch_recommended);
const totalMonthlySavings = switches.reduce((s,p) => s + (p.monthly_savings||0), 0);
const topSaving = switches.sort((a,b)=>(b.monthly_savings||0)-(a.monthly_savings||0))[0];
return [{ json: { all_products: products, switch_recommendations: switches, total_monthly_savings: totalMonthlySavings, top_opportunity: topSaving || null, products_analyzed: products.length } }];

